def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def hasDownwardPath(path, tree):
    m = len(path)
    fail = [0] * m
    k = 0
    for i in range(1, m):
        while k and path[i] != path[k]:
            k = fail[k - 1]
        if path[i] == path[k]:
            k += 1
        fail[i] = k
    vals, left, right = _links(tree)
    if not vals:
        return False
    stack = [(0, 0)]
    while stack:
        x, s = stack.pop()
        v = vals[x]
        while s and path[s] != v:
            s = fail[s - 1]
        if path[s] == v:
            s += 1
        if s == m:
            return True
        for c in (left[x], right[x]):
            if c != -1:
                stack.append((c, s))
    return False
